import math


def psi(expected, actual, floor=0.0001):
    if len(expected) != len(actual):
        raise ValueError("the histograms need the same buckets")
    expected_total, actual_total = sum(expected), sum(actual)
    if expected_total == 0 or actual_total == 0:
        raise ValueError("a histogram with no counts cannot be compared")
    total = 0.0
    for e_count, a_count in zip(expected, actual):
        e = max(e_count / expected_total, floor)
        a = max(a_count / actual_total, floor)
        total += (a - e) * math.log(a / e)
    return total
